using System.Drawing;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using FacePresence.Presence;

namespace FacePresence.App;

/// <summary>Tray icons and window images (embedded .ico/.png files from Assets, generated by docs/make_icons.py).</summary>
public static class TrayIcons
{
    private static readonly Dictionary<(string, int), Icon> Cache = new();

    private static string NameFor(PresenceState state) => state switch
    {
        PresenceState.Present => "tray_present",
        PresenceState.Absent => "tray_absent",
        PresenceState.NotEnrolled or PresenceState.Enrolling => "tray_info",
        PresenceState.CameraError => "tray_error",
        _ => "tray_idle",
    };

    /// <summary>Tray icon in the size matching the current DPI.</summary>
    public static Icon Get(PresenceState state)
    {
        var size = System.Windows.Forms.SystemInformation.SmallIconSize.Width;
        var name = NameFor(state);
        lock (Cache)
        {
            if (Cache.TryGetValue((name, size), out var cached)) return cached;
            using var stream = Open(name + ".ico");
            var icon = new Icon(stream, size, size);
            Cache[(name, size)] = icon;
            return icon;
        }
    }

    /// <summary>Application icon for WPF windows. Loaded from a PNG: the .ico frames are PNG-compressed, which WPF's
    /// icon decoder does not always accept.</summary>
    public static ImageSource AppImage => _appImage ??= LoadPng("app.png");
    private static ImageSource? _appImage;

    /// <summary>Language flag ("en"/"cs") for the switch in the window header.</summary>
    public static ImageSource Flag(string lang) => LoadPng("flag_" + lang + ".png");

    private static ImageSource LoadPng(string name)
    {
        using var stream = Open(name);
        var image = new BitmapImage();
        image.BeginInit();
        image.CacheOption = BitmapCacheOption.OnLoad;
        image.StreamSource = stream;
        image.EndInit();
        image.Freeze();
        return image;
    }

    private static Stream Open(string name) =>
        typeof(TrayIcons).Assembly.GetManifestResourceStream(name) ?? throw new InvalidOperationException("Missing resource " + name);
}
